using System.Text;using System.Text.Json;using RabbitMQ.Client;using RegistrationService.Events;namespace RegistrationService.Messaging;public sealed class RegistrationEventPublisher(IConfiguration c){public Task PublishAsync(RegistrationCreatedEvent message,CancellationToken ct){ct.ThrowIfCancellationRequested();var f=new ConnectionFactory{HostName=c["RabbitMq:Host"]??"rabbitmq",UserName=c["RabbitMq:User"]??"guest",Password=c["RabbitMq:Password"]??"guest"};using var connection=f.CreateConnection();using var channel=connection.CreateModel();channel.QueueDeclare("registration.created",durable:true,exclusive:false,autoDelete:false);var body=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message));var p=channel.CreateBasicProperties();p.Persistent=true;channel.BasicPublish("","registration.created",p,body);return Task.CompletedTask;}}